INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_020','math','คณิตศาสตร์','Gifted',5,'L5','สสวท. / โอลิมปิกวิชาการ','ถ้า log₂(x) = 1 แล้ว x = ?','["2","2","1","4"]',0,'log₂(x) = 1 หมายความว่า x = 2^1 = 2','log₂ ฐานคือ 2 ไม่ใช่ 10','log_b(x) = n ↔ x = b^n');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('MATH_L5_021','math','คณิตศาสตร์','Gifted',5,'L5','สสวท. / โอลิมปิกวิชาการ','ถ้า f(x) = x² + 21x + 22 และ f(a) = 0 แล้ว a² + 21a = ?','["-22","22","0","21"]',0,'f(a)=0 → a²+21a+22=0 → a²+21a = -22','ไม่ต้องหาค่า a จริงๆ','ใช้นิยามฟังก์ชัน f(a)=0 แทนตรงๆ');
