INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_001','science','วิทยาศาสตร์','Gifted',3,'L3','สุริยุปราคา','จันทรุปราคาเต็มดวงเกิดเมื่อดวงจันทร์เข้าสู่เงาของโลกส่วนใด (ข้อ 1)','["Umbra (เงามืดสนิท)","Penumbra (เงามัว)","Antumbra","Ombre"]',0,'Umbra คือเงามืดสนิท เมื่อดวงจันทร์เข้าสู่ Umbra จะเกิดจันทรุปราคาเต็มดวง','เลือกคำตอบที่ถูกต้องที่สุดในเชิงวิทยาศาสตร์','วิเคราะห์โดยใช้ความรู้พื้นฐาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_002','science','วิทยาศาสตร์','Gifted',3,'L3','พันธุกรรม Dihybrid','ถ้า AaBb × AaBb ลูกที่มีจีโนไทป์ AABB คิดเป็นกี่สัดส่วน (ข้อ 2)','["1/16","2/16","4/16","1/4"]',0,'P(AA)=1/4, P(BB)=1/4 → P(AABB)=1/16','เลือกคำตอบที่ถูกต้องที่สุดในเชิงวิทยาศาสตร์','วิเคราะห์โดยใช้ความรู้พื้นฐาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_003','science','วิทยาศาสตร์','Gifted',3,'L3','คลื่นและเสียง','คลื่นเสียงเดินทางได้เร็วที่สุดในตัวกลางใด (ข้อ 3)','["ของแข็ง","ของเหลว","แก๊ส","สุญญากาศ"]',0,'ของแข็งมีความยืดหยุ่นสูงสุด เสียงจึงเดินทางเร็วที่สุดในของแข็ง','เลือกคำตอบที่ถูกต้องที่สุดในเชิงวิทยาศาสตร์','วิเคราะห์โดยใช้ความรู้พื้นฐาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_004','science','วิทยาศาสตร์','Gifted',3,'L3','แรงลอยตัว','วัตถุหนัก 50 N ปริมาตร 4 ลิตร จมในน้ำ (ρ=1000 kg/m³) แรงลอยตัวคือ (ข้อ 4)','["40 N","50 N","10 N","4 N"]',0,'FB = ρVg = 1000×0.004×10 = 40 N; ≤ น้ำหนักวัตถุ จึงจม','เลือกคำตอบที่ถูกต้องที่สุดในเชิงวิทยาศาสตร์','วิเคราะห์โดยใช้ความรู้พื้นฐาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_005','science','วิทยาศาสตร์','Gifted',3,'L3','วิวัฒนาการ','ทฤษฎีวิวัฒนาการของดาร์วินอธิบายว่าสิ่งมีชีวิตที่รอดคือ (ข้อ 5)','["ปรับตัวเข้ากับสภาพแวดล้อมได้ดีที่สุด","ตัวใหญ่ที่สุด","เร็วที่สุด","แข็งแรงที่สุด"]',0,'Natural Selection: สิ่งมีชีวิตที่ปรับตัวเข้ากับสิ่งแวดล้อมได้ดีมีโอกาสรอดและสืบพันธุ์มากกว่า','เลือกคำตอบที่ถูกต้องที่สุดในเชิงวิทยาศาสตร์','วิเคราะห์โดยใช้ความรู้พื้นฐาน');
