INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_022','science','วิทยาศาสตร์','Gifted',3,'L3','พันธุกรรม Dihybrid','ถ้า AaBb × AaBb ลูกที่มีจีโนไทป์ AABB คิดเป็นกี่สัดส่วน (ข้อ 22)','["1/16","2/16","4/16","1/4"]',0,'P(AA)=1/4, P(BB)=1/4 → P(AABB)=1/16','เลือกคำตอบที่ถูกต้องที่สุดในเชิงวิทยาศาสตร์','วิเคราะห์โดยใช้ความรู้พื้นฐาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_023','science','วิทยาศาสตร์','Gifted',3,'L3','คลื่นและเสียง','คลื่นเสียงเดินทางได้เร็วที่สุดในตัวกลางใด (ข้อ 23)','["ของแข็ง","ของเหลว","แก๊ส","สุญญากาศ"]',0,'ของแข็งมีความยืดหยุ่นสูงสุด เสียงจึงเดินทางเร็วที่สุดในของแข็ง','เลือกคำตอบที่ถูกต้องที่สุดในเชิงวิทยาศาสตร์','วิเคราะห์โดยใช้ความรู้พื้นฐาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_024','science','วิทยาศาสตร์','Gifted',3,'L3','แรงลอยตัว','วัตถุหนัก 50 N ปริมาตร 4 ลิตร จมในน้ำ (ρ=1000 kg/m³) แรงลอยตัวคือ (ข้อ 24)','["40 N","50 N","10 N","4 N"]',0,'FB = ρVg = 1000×0.004×10 = 40 N; ≤ น้ำหนักวัตถุ จึงจม','เลือกคำตอบที่ถูกต้องที่สุดในเชิงวิทยาศาสตร์','วิเคราะห์โดยใช้ความรู้พื้นฐาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L3_025','science','วิทยาศาสตร์','Gifted',3,'L3','วิวัฒนาการ','ทฤษฎีวิวัฒนาการของดาร์วินอธิบายว่าสิ่งมีชีวิตที่รอดคือ (ข้อ 25)','["ปรับตัวเข้ากับสภาพแวดล้อมได้ดีที่สุด","ตัวใหญ่ที่สุด","เร็วที่สุด","แข็งแรงที่สุด"]',0,'Natural Selection: สิ่งมีชีวิตที่ปรับตัวเข้ากับสิ่งแวดล้อมได้ดีมีโอกาสรอดและสืบพันธุ์มากกว่า','เลือกคำตอบที่ถูกต้องที่สุดในเชิงวิทยาศาสตร์','วิเคราะห์โดยใช้ความรู้พื้นฐาน');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_001','science','วิทยาศาสตร์','Gifted',4,'L4','อุณหพลศาสตร์','กฎข้อที่ 1 ของอุณหพลศาสตร์กล่าวว่า (ข้อ 1)','["พลังงานไม่สูญหาย เพียงแต่เปลี่ยนรูป","เอนโทรปีของระบบปิดเพิ่มขึ้นเสมอ","วัตถุเย็นไม่ถ่ายเทความร้อนได้เอง","ความร้อนไหลจากร้อนไปเย็นเสมอ"]',0,'กฎอนุรักษ์พลังงาน: ΔU = Q - W (พลังงานภายในระบบ = ความร้อนรับ - งานที่ทำ)','วิเคราะห์เชิงลึก','ใช้กฎพื้นฐานวิทยาศาสตร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_002','science','วิทยาศาสตร์','Gifted',4,'L4','ชีวเคมี','เอนไซม์ทำงานได้ดีที่สุดในสภาวะใด (ข้อ 2)','["pH และอุณหภูมิที่เหมาะสม (Optimum)","pH ต่ำและอุณหภูมิสูง","pH สูงเสมอ","อุณหภูมิสูงเสมอ"]',0,'เอนไซม์แต่ละชนิดมี Optimum pH และอุณหภูมิ ถ้าเบี่ยงเบนจากค่านี้ประสิทธิภาพลดลง (Denaturation)','วิเคราะห์เชิงลึก','ใช้กฎพื้นฐานวิทยาศาสตร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_003','science','วิทยาศาสตร์','Gifted',4,'L4','ฟิสิกส์: โมเมนต์','คาน 2 เมตร จุดหมุนตรงกลาง แขวนน้ำหนัก 40 N ห่าง 0.5 m ต้องออกแรงกี่ N ที่ปลายอีกด้าน (ข้อ 3)','["20 N","40 N","10 N","80 N"]',0,'Moment = F×d: 40×0.5 = F×1 → F = 20 N','ระยะจากจุดหมุนถึงจุดออกแรง = 1 m','Σmoment=0 เมื่อสมดุล');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_004','science','วิทยาศาสตร์','Gifted',4,'L4','เคมี: ปฏิกิริยาออกซิเดชัน','ในปฏิกิริยา: Fe + 2HCl → FeCl₂ + H₂ ธาตุใดถูกออกซิไดซ์ (ข้อ 4)','["Fe","Cl","H","ทุกธาตุ"]',0,'Fe เลขออกซิเดชันเปลี่ยน 0→+2 (เสียอิเล็กตรอน) = ถูกออกซิไดซ์','วิเคราะห์เชิงลึก','ใช้กฎพื้นฐานวิทยาศาสตร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_005','science','วิทยาศาสตร์','Gifted',4,'L4','ชีววิทยา: ระบบประสาท','Reflex arc ผ่านโครงสร้างตามลำดับใด (ข้อ 5)','["Receptor → Sensory neuron → Spinal cord → Motor neuron → Effector","Receptor → Motor → Brain → Sensory → Effector","Brain → Motor → Receptor → Spinal → Effector","Effector → Brain → Receptor → Sensory"]',0,'การสะท้อนกลับผ่าน Receptor→อวัยวะรับ→Sensory neuron→ไขสันหลัง→Motor neuron→Effector','วิเคราะห์เชิงลึก','ใช้กฎพื้นฐานวิทยาศาสตร์');
