INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_018','science','วิทยาศาสตร์','Gifted',4,'L4','ฟิสิกส์: โมเมนต์','คาน 2 เมตร จุดหมุนตรงกลาง แขวนน้ำหนัก 40 N ห่าง 0.5 m ต้องออกแรงกี่ N ที่ปลายอีกด้าน (ข้อ 18)','["20 N","40 N","10 N","80 N"]',0,'Moment = F×d: 40×0.5 = F×1 → F = 20 N','ระยะจากจุดหมุนถึงจุดออกแรง = 1 m','Σmoment=0 เมื่อสมดุล');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_019','science','วิทยาศาสตร์','Gifted',4,'L4','เคมี: ปฏิกิริยาออกซิเดชัน','ในปฏิกิริยา: Fe + 2HCl → FeCl₂ + H₂ ธาตุใดถูกออกซิไดซ์ (ข้อ 19)','["Fe","Cl","H","ทุกธาตุ"]',0,'Fe เลขออกซิเดชันเปลี่ยน 0→+2 (เสียอิเล็กตรอน) = ถูกออกซิไดซ์','วิเคราะห์เชิงลึก','ใช้กฎพื้นฐานวิทยาศาสตร์');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L4_020','science','วิทยาศาสตร์','Gifted',4,'L4','ชีววิทยา: ระบบประสาท','Reflex arc ผ่านโครงสร้างตามลำดับใด (ข้อ 20)','["Receptor → Sensory neuron → Spinal cord → Motor neuron → Effector","Receptor → Motor → Brain → Sensory → Effector","Brain → Motor → Receptor → Spinal → Effector","Effector → Brain → Receptor → Sensory"]',0,'การสะท้อนกลับผ่าน Receptor→อวัยวะรับ→Sensory neuron→ไขสันหลัง→Motor neuron→Effector','วิเคราะห์เชิงลึก','ใช้กฎพื้นฐานวิทยาศาสตร์');
