INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_001','science','วิทยาศาสตร์','Gifted',5,'L5','ควอนตัมฟิสิกส์','หลักความไม่แน่นอนของไฮเซนเบิร์กกล่าวว่า (ข้อ 1)','["ไม่สามารถวัดตำแหน่งและโมเมนตัมพร้อมกันได้อย่างแม่นยำทั้งคู่","อิเล็กตรอนหมุนรอบนิวเคลียส","แสงมีธรรมชาติแบบคลื่นและอนุภาค","พลังงานมีค่าต่อเนื่อง"]',0,'Δx·Δp ≥ ℏ/2 — ความแม่นยำตำแหน่งกับโมเมนตัมมี trade-off กัน','วิเคราะห์เชิงลึกระดับโอลิมปิก','ใช้หลักการฟิสิกส์/เคมีขั้นสูง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_002','science','วิทยาศาสตร์','Gifted',5,'L5','เคมีอินทรีย์','สารอินทรีย์ที่มีหมู่ฟังก์ชัน -COOH เรียกว่า (ข้อ 2)','["กรดคาร์บอกซิลิก","แอลกอฮอล์","เอสเทอร์","แอมีน"]',0,'-COOH คือหมู่ Carboxyl เป็นลักษณะเฉพาะของกรดคาร์บอกซิลิก (Carboxylic Acid)','วิเคราะห์เชิงลึกระดับโอลิมปิก','ใช้หลักการฟิสิกส์/เคมีขั้นสูง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_003','science','วิทยาศาสตร์','Gifted',5,'L5','ชีวฟิสิกส์: ATP','ATP สังเคราะห์ใน mitochondria ผ่านกระบวนการหลักใด (ข้อ 3)','["Oxidative phosphorylation","Substrate-level phosphorylation","Photophosphorylation","Fermentation"]',0,'Oxidative phosphorylation ผ่าน ETC (Electron Transport Chain) สร้าง ATP จำนวนมากที่สุด ~32-34 ATP','วิเคราะห์เชิงลึกระดับโอลิมปิก','ใช้หลักการฟิสิกส์/เคมีขั้นสูง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_004','science','วิทยาศาสตร์','Gifted',5,'L5','ดาราศาสตร์','Magnitude -1.46 ของดาวซิริอุสหมายความว่า (ข้อ 4)','["สว่างมาก ค่าน้อย=สว่างกว่า","มืดมาก","อยู่ใกล้โลก","อุณหภูมิสูง"]',0,'Apparent Magnitude: ค่าน้อยหรือติดลบ = สว่างกว่า ดาวซิริอุสเป็นดาวที่สว่างที่สุดบนฟ้ายามค่ำคืน','วิเคราะห์เชิงลึกระดับโอลิมปิก','ใช้หลักการฟิสิกส์/เคมีขั้นสูง');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SCI_L5_005','science','วิทยาศาสตร์','Gifted',5,'L5','ฟิสิกส์นิวเคลียร์','การสลายตัวแบบ Alpha จะทำให้เลขอะตอม (Z) และเลขมวล (A) เปลี่ยนอย่างไร (ข้อ 5)','["Z-2 และ A-4","Z-1 และ A","Z+1 และ A","Z และ A-1"]',0,'Alpha decay: ปล่อย ₂⁴He → Z ลด 2, A ลด 4','วิเคราะห์เชิงลึกระดับโอลิมปิก','ใช้หลักการฟิสิกส์/เคมีขั้นสูง');
