INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_001','social','สังคมศึกษา','Gifted',3,'L3','กฎหมาย','หลักนิติธรรม (Rule of Law) สำคัญอย่างไร (ข้อ 1)','["ทุกคนอยู่ภายใต้กฎหมายเท่าเทียมกัน รวมทั้งรัฐบาล","กฎหมายเปลี่ยนได้ตามใจผู้ปกครอง","ผู้มีอำนาจอยู่เหนือกฎหมาย","กฎหมายใช้กับประชาชนเท่านั้น"]',0,'Rule of Law: รัฐและประชาชนทุกคนต้องอยู่ใต้กฎหมาย ไม่มีใครอยู่เหนือกฎหมาย','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L3_002','social','สังคมศึกษา','Gifted',3,'L3','ประวัติศาสตร์ไทย','เหตุการณ์ใด พ.ศ. 2475 เปลี่ยนแปลงการปกครองไทย (ข้อ 2)','["การปฏิวัติสยาม เปลี่ยนจากสมบูรณาญาสิทธิราชย์เป็นประชาธิปไตย","สงครามโลกครั้งที่ 2","การเสียกรุงครั้งที่ 2","การตั้งกรุงรัตนโกสินทร์"]',0,'2475: คณะราษฎรเปลี่ยนการปกครองจากสมบูรณาญาสิทธิราชย์เป็นราชาธิปไตยภายใต้รัฐธรรมนูญ','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
