INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_001','social','สังคมศึกษา','Gifted',4,'L4','รัฐธรรมนูญเปรียบเทียบ','ระบบสหพันธรัฐ (Federal System) แตกต่างจากรัฐเดี่ยวอย่างไร (ข้อ 1)','["มีรัฐบาลกลางและรัฐบาลท้องถิ่นที่มีอำนาจปกครองตนเอง","มีรัฐบาลเดียวควบคุมทั้งประเทศ","ไม่มีรัฐสภา","ปกครองโดยกษัตริย์เพียงพระองค์เดียว"]',0,'Federal: อำนาจแบ่งระหว่างรัฐบาลกลาง (Federal) และมลรัฐ (State) เช่น USA','สหพันธรัฐ ≠ สหภาพ','Federal = ศูนย์กลาง + ส่วนย่อยมีอำนาจ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_002','social','สังคมศึกษา','Gifted',4,'L4','เศรษฐศาสตร์ระหว่างประเทศ','ทฤษฎีความได้เปรียบเปรียบเทียบ (Comparative Advantage) เสนอโดยใคร (ข้อ 2)','["David Ricardo","Adam Smith","Karl Marx","John Keynes"]',0,'David Ricardo เสนอทฤษฎีว่าประเทศควรผลิตสินค้าที่มีต้นทุนโอกาสต่ำกว่า','Adam Smith เสนอ Absolute Advantage','Ricardo = Comparative; Smith = Absolute');
