INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_004','social','สังคมศึกษา','Gifted',4,'L4','สังคมวิทยา','ทฤษฎีหน้าที่นิยม (Functionalism) ในสังคมวิทยามองสังคมว่า (ข้อ 4)','["เป็นระบบที่แต่ละส่วนทำหน้าที่ร่วมกันรักษาความสมดุล","เป็นสนามแห่งการต่อสู้ชนชั้น","เป็นผลผลิตของภาษาและวาทกรรม","เปลี่ยนแปลงตามวิวัฒนาการ"]',0,'Functionalism (Durkheim, Parsons): สังคมคือระบบที่แต่ละสถาบันทำหน้าที่เพื่อรักษาดุลยภาพ','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
