INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_021','social','สังคมศึกษา','Gifted',4,'L4','รัฐธรรมนูญเปรียบเทียบ','ระบบสหพันธรัฐ (Federal System) แตกต่างจากรัฐเดี่ยวอย่างไร (ข้อ 21)','["มีรัฐบาลกลางและรัฐบาลท้องถิ่นที่มีอำนาจปกครองตนเอง","มีรัฐบาลเดียวควบคุมทั้งประเทศ","ไม่มีรัฐสภา","ปกครองโดยกษัตริย์เพียงพระองค์เดียว"]',0,'Federal: อำนาจแบ่งระหว่างรัฐบาลกลาง (Federal) และมลรัฐ (State) เช่น USA','สหพันธรัฐ ≠ สหภาพ','Federal = ศูนย์กลาง + ส่วนย่อยมีอำนาจ');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_022','social','สังคมศึกษา','Gifted',4,'L4','เศรษฐศาสตร์ระหว่างประเทศ','ทฤษฎีความได้เปรียบเปรียบเทียบ (Comparative Advantage) เสนอโดยใคร (ข้อ 22)','["David Ricardo","Adam Smith","Karl Marx","John Keynes"]',0,'David Ricardo เสนอทฤษฎีว่าประเทศควรผลิตสินค้าที่มีต้นทุนโอกาสต่ำกว่า','Adam Smith เสนอ Absolute Advantage','Ricardo = Comparative; Smith = Absolute');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_023','social','สังคมศึกษา','Gifted',4,'L4','ภูมิรัฐศาสตร์','การที่จีนเรียกร้องอธิปไตยในทะเลจีนใต้เรียกว่า (ข้อ 23)','["Nine-Dash Line","One Belt One Road","Asia Pacific","ASEAN Claim"]',0,'Nine-Dash Line คือเส้นประ 9 เส้นที่จีนอ้างสิทธิ์ครอบคลุมทะเลจีนใต้กว่า 80%','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L4_024','social','สังคมศึกษา','Gifted',4,'L4','สังคมวิทยา','ทฤษฎีหน้าที่นิยม (Functionalism) ในสังคมวิทยามองสังคมว่า (ข้อ 24)','["เป็นระบบที่แต่ละส่วนทำหน้าที่ร่วมกันรักษาความสมดุล","เป็นสนามแห่งการต่อสู้ชนชั้น","เป็นผลผลิตของภาษาและวาทกรรม","เปลี่ยนแปลงตามวิวัฒนาการ"]',0,'Functionalism (Durkheim, Parsons): สังคมคือระบบที่แต่ละสถาบันทำหน้าที่เพื่อรักษาดุลยภาพ','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
