INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_001','social','สังคมศึกษา','Gifted',5,'L5','ปรัชญาการเมือง','Social Contract Theory ของ John Locke กล่าวว่า (ข้อ 1)','["รัฐบาลได้รับอำนาจจากความยินยอมของผู้ปกครอง และประชาชนมีสิทธิปฏิวัติถ้ารัฐบาลละเมิดสัญญา","อำนาจรัฐมาจากพระเจ้า","มนุษย์เป็นสัตว์สังคมโดยธรรมชาติ","รัฐควรเป็นองค์อธิปัตย์ที่แน่วแน่"]',0,'Locke เน้น Natural Rights (ชีวิต เสรีภาพ ทรัพย์สิน) และสิทธิต่อต้านรัฐที่ทรราช','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_002','social','สังคมศึกษา','Gifted',5,'L5','ทฤษฎีเศรษฐศาสตร์','Keynesian Economics เสนอวิธีแก้เศรษฐกิจตกต่ำด้วย (ข้อ 2)','["รัฐเพิ่มการใช้จ่าย (Fiscal Stimulus) กระตุ้นอุปสงค์","ลดภาษีและปล่อยตลาดเสรี","ลดปริมาณเงิน","เพิ่มอัตราดอกเบี้ย"]',0,'Keynes เชื่อว่าตลาดไม่สมดุลเองได้ รัฐต้องแทรกแซงผ่านนโยบายการคลัง','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_003','social','สังคมศึกษา','Gifted',5,'L5','มานุษยวิทยา','การศึกษา "Ethnography" คือ (ข้อ 3)','["การลงภาคสนามสังเกตวัฒนธรรมของกลุ่มชาติพันธุ์","การศึกษาโบราณคดี","การวิจัยเชิงปริมาณ","การสัมภาษณ์เชิงสถิติ"]',0,'Ethnography: นักมานุษยวิทยาเข้าไปอยู่ในชุมชนเพื่อสังเกตวิถีชีวิตโดยตรง','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_004','social','สังคมศึกษา','Gifted',5,'L5','ภูมิศาสตร์มนุษย์','Gentrification หมายถึง (ข้อ 4)','["การปรับปรุงย่านเก่าให้ทันสมัยจนผู้มีรายได้น้อยถูกขับออก","การขยายตัวของเมือง","การพัฒนาชนบท","การย้ายถิ่นฐานสู่เมือง"]',0,'Gentrification: เมื่อย่านเก่าถูกพัฒนา ราคาที่ดินสูงขึ้น ผู้มีรายได้น้อยไม่สามารถอยู่ต่อได้','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_005','social','สังคมศึกษา','Gifted',5,'L5','กฎหมายระหว่างประเทศ','หลักการ "R2P" (Responsibility to Protect) กล่าวถึง (ข้อ 5)','["ประชาคมโลกมีหน้าที่แทรกแซงปกป้องพลเรือนจากการฆ่าล้างเผ่าพันธุ์","สิทธิส่วนบุคคล","อธิปไตยรัฐ","เสรีการค้า"]',0,'R2P รับรองโดย UN 2005: ถ้ารัฐล้มเหลวปกป้องพลเมือง ประชาคมโลกมีสิทธิ์แทรกแซง','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
