INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_014','social','สังคมศึกษา','Gifted',5,'L5','ภูมิศาสตร์มนุษย์','Gentrification หมายถึง (ข้อ 14)','["การปรับปรุงย่านเก่าให้ทันสมัยจนผู้มีรายได้น้อยถูกขับออก","การขยายตัวของเมือง","การพัฒนาชนบท","การย้ายถิ่นฐานสู่เมือง"]',0,'Gentrification: เมื่อย่านเก่าถูกพัฒนา ราคาที่ดินสูงขึ้น ผู้มีรายได้น้อยไม่สามารถอยู่ต่อได้','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_015','social','สังคมศึกษา','Gifted',5,'L5','กฎหมายระหว่างประเทศ','หลักการ "R2P" (Responsibility to Protect) กล่าวถึง (ข้อ 15)','["ประชาคมโลกมีหน้าที่แทรกแซงปกป้องพลเรือนจากการฆ่าล้างเผ่าพันธุ์","สิทธิส่วนบุคคล","อธิปไตยรัฐ","เสรีการค้า"]',0,'R2P รับรองโดย UN 2005: ถ้ารัฐล้มเหลวปกป้องพลเมือง ประชาคมโลกมีสิทธิ์แทรกแซง','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
INSERT INTO questions (id,subject,subject_name,track,difficulty,level,topic,question,options_json,correct_answer,explanation,trap,shortcut_trick) VALUES ('SOC_L5_016','social','สังคมศึกษา','Gifted',5,'L5','ปรัชญาการเมือง','Social Contract Theory ของ John Locke กล่าวว่า (ข้อ 16)','["รัฐบาลได้รับอำนาจจากความยินยอมของผู้ปกครอง และประชาชนมีสิทธิปฏิวัติถ้ารัฐบาลละเมิดสัญญา","อำนาจรัฐมาจากพระเจ้า","มนุษย์เป็นสัตว์สังคมโดยธรรมชาติ","รัฐควรเป็นองค์อธิปัตย์ที่แน่วแน่"]',0,'Locke เน้น Natural Rights (ชีวิต เสรีภาพ ทรัพย์สิน) และสิทธิต่อต้านรัฐที่ทรราช','อ่านคำถามให้ครบก่อน','จำแนกหลักฐานออกจากความเห็น');
